class_name BotDriver extends Node
## Scripted command producer for automated role tests. Produces the exact same
## ActorCommand Dictionaries as a human; turn rate is capped at `look_rate`
## rad/s so mech vs pilot comparisons go through identical input plumbing.

var subject: Node3D            # controller being driven (needs .yaw/.pitch)
var look_rate := 2.6           # rad/s cap on produced look commands
var steps: Array = []          # see _step helpers below
var done := false

var _i := 0
var _t := 0.0


static func goto(pos: Vector3, arrive := 1.6) -> Dictionary:
	return {"type": "goto", "pos": pos, "arrive": arrive}


## Move to pos, then engage enemies while holding there.
## prefer_priority: aim at group "priority" targets first when present.
## allow_rockets: press fire_s whenever salvo is ready.
static func combat(pos: Vector3, prefer_priority := false, allow_rockets := false) -> Dictionary:
	return {"type": "combat", "pos": pos, "prefer_priority": prefer_priority,
			"allow_rockets": allow_rockets}


static func wait(dur: float) -> Dictionary:
	return {"type": "wait", "dur": dur}


func reset() -> void:
	_i = 0
	_t = 0.0
	done = false


func poll(dt: float) -> Dictionary:
	if done or steps.is_empty() or subject == null:
		return ActorIface.empty_command()
	_t += dt
	var s: Dictionary = steps[_i]
	match s.type:
		"wait":
			if _t >= float(s.dur):
				_advance()
			return ActorIface.empty_command()
		"goto":
			return _step_goto(s)
		"combat":
			return _step_combat(s)
	return ActorIface.empty_command()


func _advance() -> void:
	_i += 1
	_t = 0.0
	if _i >= steps.size():
		done = true


func _step_goto(s: Dictionary) -> Dictionary:
	var to := (Vector3(s.pos) - subject.global_position)
	to.y = 0.0
	if to.length() <= float(s.arrive):
		_advance()
		return ActorIface.empty_command()
	var fwd := -subject.global_transform.basis.z
	fwd.y = 0.0
	fwd = fwd.normalized()
	# +X is right in Godot's -Z-forward basis.
	var right := Vector3(fwd.z, 0.0, -fwd.x)
	var local := Vector2(right.dot(to.normalized()), -fwd.dot(to.normalized()))
	local = local.limit_length(1.0)
	var aim := _look_toward(subject.global_position + to)
	return ActorIface.make_command(local, aim)


func _step_combat(s: Dictionary) -> Dictionary:
	var to := (Vector3(s.pos) - subject.global_position)
	to.y = 0.0
	var mv := Vector2.ZERO
	# Standoff: hold ground once anything is in effective range - bots must
	# not walk into the target's melee ring (or the mech's close blind zone).
	if _nearest_enemy_dist() > 13.0 and to.length() > 2.0:
		var fwd := -subject.global_transform.basis.z
		fwd.y = 0.0
		fwd = fwd.normalized()
		var right := Vector3(fwd.z, 0.0, -fwd.x)
		mv = Vector2(right.dot(to.normalized()), -fwd.dot(to.normalized())).limit_length(1.0)
	var target := _pick_target(bool(s.prefer_priority))
	if target == null:
		if mv == Vector2.ZERO:
			# Nothing to shoot and nowhere to go: idle scan slowly.
			return ActorIface.make_command(mv, Vector2(0.4 * signf(sin(_t * 0.7)), 0.0))
		return ActorIface.make_command(mv, Vector2.ZERO)
	var aim := _look_toward(_aim_point(target))
	var cmd := ActorIface.make_command(mv, aim, false, true, false)
	cmd["fire_s"] = bool(s.allow_rockets) and _rockets_ready()
	return cmd


func _nearest_enemy_dist() -> float:
	var best := INF
	for n in subject.get_tree().get_nodes_in_group("enemies"):
		var n3 := n as Node3D
		if n3 != null and _alive(n3):
			best = minf(best, n3.global_position.distance_to(subject.global_position))
	return best


func _pick_target(prefer_priority: bool) -> Node3D:
	var best: Node3D = null
	var best_d := INF
	for n in subject.get_tree().get_nodes_in_group("enemies"):
		var n3 := n as Node3D
		if n3 != null and _alive(n3):
			var d := n3.global_position.distance_squared_to(subject.global_position)
			if d < best_d:
				best_d = d
				best = n3
	# Priority-first, but only when it is actually pressing - otherwise the
	# holder must clear the pressure stream instead of plinking a far tank.
	if best != null and prefer_priority:
		for n in subject.get_tree().get_nodes_in_group("priority"):
			var n3 := n as Node3D
			if n3 != null and _alive(n3):
				var d := n3.global_position.distance_to(subject.global_position)
				if d <= sqrt(best_d) * 1.1:
					return n3
	return best


func _alive(n: Node) -> bool:
	var h := n.get_node_or_null("Health") as Health
	return h == null or h.state != ActorIface.ActorState.DESTROYED


func _aim_point(target: Node3D) -> Vector3:
	return target.global_position + Vector3.UP * 1.0


func _eye_pos() -> Vector3:
	if subject != null and subject.has_method("aim_eye"):
		return subject.call("aim_eye")
	return subject.global_position + Vector3.UP * 1.5


## Desired yaw/pitch rate toward a world point, capped at look_rate.
func _look_toward(point: Vector3) -> Vector2:
	var d := point - _eye_pos()
	if d.length_squared() < 0.001:
		return Vector2.ZERO
	var want_yaw := atan2(-d.x, -d.z)
	var want_pitch := asin(clampf(d.normalized().y, -1.0, 1.0))
	var dy := wrapf(want_yaw - subject.yaw, -PI, PI)
	var dp := wrapf(want_pitch - subject.pitch, -PI, PI)
	# Command convention: positive look.x/y DECREASES yaw / pitch.
	# Proportional term (rate = 16x error, capped) = a skilled operator:
	# crisp lock without pursuit-orbits, same input budget for both actors.
	return Vector2(
			clampf(-dy * 16.0, -look_rate, look_rate),
			clampf(-dp * 16.0, -look_rate, look_rate))


func _rockets_ready() -> bool:
	var w := subject.get_node_or_null("Weapons") as MechWeapons
	return w != null and w.rockets_ready()

class_name Health extends Node
## Hull/HP component. Consumes DamageEvents, exposes ActorState transitions.

signal hull_changed(fraction: float)
signal state_changed(new_state: int)
signal destroyed(evt: Dictionary)

@export var max_hp := 100.0
@export var damaged_at := 0.5
@export var critical_at := 0.25

var hp := 100.0
var state: int = ActorIface.ActorState.ALIVE


func _ready() -> void:
	hp = max_hp
	state = ActorIface.ActorState.ALIVE


func fraction() -> float:
	return hp / max_hp


func take_damage(evt: Dictionary) -> void:
	if state == ActorIface.ActorState.DESTROYED:
		return
	hp = maxf(hp - float(evt.get("amount", 0.0)), 0.0)
	hull_changed.emit(fraction())
	var s := _state_for_fraction()
	if s != state:
		state = s
		state_changed.emit(s)
	if hp <= 0.0:
		state = ActorIface.ActorState.DESTROYED
		state_changed.emit(state)
		destroyed.emit(evt)


func repair_full() -> void:
	hp = max_hp
	var s := _state_for_fraction()
	if s != state:
		state = s
		state_changed.emit(s)
	hull_changed.emit(1.0)


func _state_for_fraction() -> int:
	var f := fraction()
	if f <= critical_at:
		return ActorIface.ActorState.CRITICAL
	if f <= damaged_at:
		return ActorIface.ActorState.DAMAGED
	return ActorIface.ActorState.ALIVE

class_name Hud extends CanvasLayer
## Greybox HUD. For the mech it is explicit COMPENSATION for the lost
## situational awareness: threat-direction arrows, lane status, teammate
## marker (drawn through walls on purpose), hull/heat/rocket gauges.

var snap := {}
var _overlay: Control
var _fade: ColorRect
var _fade_tween: Tween
var wave_text := ""
var wave_text_t := 0.0
var ex_text := ""
var extraction_countdown := 0.0
var _t := 0.0


func _ready() -> void:
	layer = 10
	_overlay = Control.new()
	_overlay.set_anchors_preset(Control.PRESET_FULL_RECT)
	_overlay.mouse_filter = Control.MOUSE_FILTER_IGNORE   # never eat mouse input
	_overlay.draw.connect(_draw_overlay)
	add_child(_overlay)
	# Embark/disembark fade (плавное переключение камер/мешей).
	_fade = ColorRect.new()
	_fade.color = Color(0, 0, 0, 0)
	_fade.set_anchors_preset(Control.PRESET_FULL_RECT)
	_fade.mouse_filter = Control.MOUSE_FILTER_IGNORE
	add_child(_fade)


## Quick black dip covering the mesh/camera swap on enter/exit/destroy.
func transition(dur := 0.28) -> void:
	if _fade_tween != null and _fade_tween.is_valid():
		_fade_tween.kill()
	_fade.color.a = 1.0
	_fade_tween = create_tween()
	_fade_tween.tween_property(_fade, "color:a", 0.0, dur)


func update_snap(s: Dictionary) -> void:
	snap = s
	_t += 1.0 / 60.0
	if wave_text_t > 0.0:
		wave_text_t -= 1.0 / 60.0
	if extraction_countdown > 0.0:
		extraction_countdown = maxf(extraction_countdown - 1.0 / 60.0, 0.0)
	_overlay.queue_redraw()


func _font() -> Font:
	return ThemeDB.fallback_font


func _draw_overlay() -> void:
	var vp := _overlay.get_viewport_rect().size
	var c := vp * 0.5
	var mode: String = snap.get("mode", "pilot")

	# --- Wave banner (VS-7) + EX/greed (VS-8).
	if wave_text_t > 0.0:
		_centered(wave_text, Vector2(c.x, 86),
				Color(1.0, 0.8, 0.3), 20)
	if extraction_countdown > 0.0:
		_centered("EXTRACTION WINDOW %ds — G: GREEDY = bonus wave" %
				int(ceil(extraction_countdown)), Vector2(c.x, 112),
				Color(0.5, 1.0, 0.6), 15)
	if ex_text != "":
		_centered(ex_text, Vector2(c.x, 62), Color(0.5, 1.0, 0.6), 15)

	# --- Crosshair (+ rotary spin arc in mech mode).
	var spin: float = snap.get("spin", 0.0)
	var col := Color(0.9, 0.9, 0.9)
	if snap.get("locked", false):
		col = Color(1.0, 0.25, 0.2)
	_overlay.draw_circle(c, 2.5, col)
	_overlay.draw_arc(c, 14.0, -PI / 2, -PI / 2 + TAU * spin, 24,
			Color(1.0, 0.75, 0.2) if spin < 1.0 else Color(0.4, 1.0, 0.5), 2.5)

	# --- Bottom-left gauges.
	var x := 24.0
	var y := vp.y - 96.0
	if mode == "mech":
		_bar(x, y, 220, 12, snap.get("hp_frac", 1.0), Color(0.3, 0.9, 0.4))
		_label("HULL %s" % snap.get("state_text", ""), Vector2(x, y - 16),
				Color(0.85, 0.85, 0.85))
		_bar(x, y + 22, 160, 8, snap.get("heat", 0.0) / snap.get("max_heat", 100.0),
				Color(1.0, 0.55, 0.15))
		_label("HEAT/OVERHEAT", Vector2(x, y + 32), Color(0.7, 0.7, 0.7))
		var rockets: int = snap.get("rockets", 6)
		for i in range(6):
			var rcol := Color(0.35, 0.7, 1.0) if i < rockets else Color(0.25, 0.25, 0.28)
			_overlay.draw_rect(Rect2(x + 180 + i * 16, y + 22, 11, 11), rcol)
	else:
		_bar(x, y, 220, 12, snap.get("hp_frac", 1.0), Color(0.3, 0.9, 0.4))
		_label("PILOT %s" % snap.get("state_text", ""), Vector2(x, y - 16),
				Color(0.85, 0.85, 0.85))

	# --- Top-center: Core bar + lane pips.
	var cw := 320.0
	_bar(c.x - cw / 2, 18, cw, 10, snap.get("core_frac", 1.0), Color(0.2, 0.8, 1.0))
	_label("CORE", Vector2(c.x - cw / 2, 24), Color(0.7, 0.9, 1.0))
	var lanes: Dictionary = snap.get("lanes", {})
	var lx := c.x - 120.0
	for lname in ["A", "B"]:
		var lane: Dictionary = lanes.get(lname, {})
		var breach: int = int(lane.get("breach", 0))
		var lcol := Color(0.3, 0.9, 0.4)
		if breach >= 2:
			lcol = Color(1.0, 0.3, 0.2)
		elif breach >= 1:
			lcol = Color(1.0, 0.7, 0.15)
		_label("LANE %s" % lname, Vector2(lx, 44), Color(0.8, 0.8, 0.8))
		var intact := clampi(3 - breach, 0, 3)
		for i in range(3):
			var pip := lcol if i < intact else Color(0.25, 0.25, 0.28)
			_overlay.draw_rect(Rect2(lx + i * 18, 56, 13, 13), pip)
		lx += 130.0

	# --- Threat cues + teammate marker.
	_draw_threats(vp)
	_draw_teammate(vp)

	# --- Banners + hints.
	var by := vp.y * 0.30
	for b: String in snap.get("banners", []):
		var flash := fmod(_t, 0.7) < 0.45
		_centered(b, Vector2(c.x, by), Color(1.0, 0.3, 0.2) if flash else Color(0.6, 0.2, 0.15), 22)
		by += 26.0
	var hint: String = snap.get("hint", "")
	if hint != "":
		_centered(hint, Vector2(c.x, vp.y - 140), Color(0.95, 0.95, 0.6), 16)


func _bar(x: float, y: float, w: float, h: float, frac: float, col: Color) -> void:
	frac = clampf(frac, 0.0, 1.0)
	_overlay.draw_rect(Rect2(x, y, w, h), Color(0, 0, 0, 0.55))
	_overlay.draw_rect(Rect2(x, y, w * frac, h), col)
	_overlay.draw_rect(Rect2(x, y, w, h), Color(1, 1, 1, 0.25), false, 1.0)


func _label(text: String, pos: Vector2, col: Color, size := 12) -> void:
	_overlay.draw_string(_font(), pos, text, HORIZONTAL_ALIGNMENT_LEFT, -1, size, col)


func _centered(text: String, pos: Vector2, col: Color, size := 14) -> void:
	var w := _font().get_string_size(text, HORIZONTAL_ALIGNMENT_LEFT, -1, size).x
	_overlay.draw_string(_font(), pos - Vector2(w / 2, 0), text,
			HORIZONTAL_ALIGNMENT_LEFT, -1, size, col)


func _edge_point(vp: Vector2, dir_screen: Vector2) -> Vector2:
	# Point on a rect inset 40px toward the direction from center.
	var c := vp * 0.5
	var d := dir_screen.normalized()
	var tx := INF if d.x <= 0 else (vp.x - 40 - c.x) / d.x
	var tx_neg := INF if d.x >= 0 else (40 - c.x) / d.x
	var ty := INF if d.y <= 0 else (vp.y - 40 - c.y) / d.y
	var ty_neg := INF if d.y >= 0 else (40 - c.y) / d.y
	var t: float = minf(minf(tx, tx_neg), minf(ty, ty_neg))
	return c + d * t


func _arrow(at: Vector2, dir_screen: Vector2, col: Color) -> void:
	var d := dir_screen.normalized()
	var p := at
	var pts := PackedVector2Array([p + d * 10, p + d.rotated(2.5) * 4,
			p + d.rotated(-2.5) * 4])
	_overlay.draw_colored_polygon(pts, col)


func _draw_threats(vp: Vector2) -> void:
	var cam := get_viewport().get_camera_3d()
	if cam == null:
		return
	# Threat feed comes pre-filtered in the snapshot (Director/network).
	for t: Dictionary in snap.get("threats", []):
		var wp: Vector3 = t.pos
		var armored := bool(t.get("armored", false))
		var behind := cam.is_position_behind(wp)
		var sp := cam.unproject_position(wp)
		var col := Color(1.0, 0.55, 0.1) if armored else Color(1.0, 0.25, 0.2)
		if behind or sp.x < 60 or sp.x > vp.x - 60 or sp.y < 60 or sp.y > vp.y - 60:
			# Off-view: edge arrow = awareness compensation.
			var flat := wp - cam.global_position
			var right := cam.global_basis.x
			var up := cam.global_basis.y
			var dir_screen := Vector2(right.dot(flat), -up.dot(flat))
			_arrow(_edge_point(vp, dir_screen), dir_screen, col)
		else:
			_overlay.draw_arc(sp, 9.0, 0, TAU, 12, Color(col, 0.8), 1.5)


func _draw_teammate(vp: Vector2) -> void:
	var mate: Node3D = snap.get("teammate")
	var cam := get_viewport().get_camera_3d()
	if mate == null or not is_instance_valid(mate) or cam == null:
		return
	# NOTE: the marker is drawn even for hidden actors on purpose - in mech
	# mode the embarked pilot is hidden, but the partner marker must persist.
	var wp := mate.global_position + Vector3.UP * 2.2
	var behind := cam.is_position_behind(wp)
	var sp := cam.unproject_position(wp) if not behind else Vector2.ZERO
	var col := Color(0.3, 1.0, 0.5)
	if behind or sp.x < 0 or sp.x > vp.x or sp.y < 0 or sp.y > vp.y:
		var flat := wp - cam.global_position
		var dir_screen := Vector2(cam.global_basis.x.dot(flat),
				-cam.global_basis.y.dot(flat))
		sp = _edge_point(vp, dir_screen)
		_arrow(sp, dir_screen, col)
	else:
		var p := sp
		var pts := PackedVector2Array([p + Vector2(0, -8), p + Vector2(7, 0),
				p + Vector2(0, 8), p + Vector2(-7, 0)])
		_overlay.draw_colored_polygon(pts, Color(col, 0.9))

class_name InputSource extends Node
## Local human input -> ActorCommand. Registers named actions at runtime;
## production game/ should move these into project.godot InputMap and reuse
## the same action names so remapping keeps working without touching controllers.

const ACTIONS := {
	"move_forward": [KEY_W],
	"move_back": [KEY_S],
	"move_left": [KEY_A],
	"move_right": [KEY_D],
	"jump": [KEY_SPACE],
	"interact": [KEY_E],
	"toggle_greed": [KEY_G],
}

var enabled := true
var look_sensitivity := 0.0021   # rad per screen px
## Own capture flag: DisplayServer-independent (headless tests work too).
## Windowed cursor capture is toggled with ESC (ui_cancel).
var mouse_captured := true

var _look_accum := Vector2.ZERO


func _enter_tree() -> void:
	for action: String in ACTIONS:
		if not InputMap.has_action(action):
			InputMap.add_action(action)
			for key: Key in ACTIONS[action]:
				var ev := InputEventKey.new()
				ev.physical_keycode = key
				InputMap.action_add_event(action, ev)
	for pair in [["fire_primary", MOUSE_BUTTON_LEFT], ["fire_secondary", MOUSE_BUTTON_RIGHT]]:
		if not InputMap.has_action(pair[0]):
			InputMap.add_action(pair[0])
			var mb := InputEventMouseButton.new()
			mb.button_index = pair[1]
			InputMap.action_add_event(pair[0], mb)


## _input (not _unhandled_input) so GUI layers can never swallow mouse look.
func _input(e: InputEvent) -> void:
	if e.is_action_pressed("ui_cancel"):
		mouse_captured = not mouse_captured
		Input.mouse_mode = (Input.MOUSE_MODE_CAPTURED if mouse_captured
				else Input.MOUSE_MODE_VISIBLE)
	elif e is InputEventMouseMotion and mouse_captured:
		_look_accum += (e as InputEventMouseMotion).relative * look_sensitivity


## Called once per physics tick by the Director. look = instantaneous turn rate.
func poll(dt: float) -> Dictionary:
	if not enabled:
		return ActorIface.empty_command()
	var mv := Input.get_vector("move_left", "move_right", "move_forward", "move_back")
	var rate := Vector2.ZERO
	if dt > 0.0:
		rate = (_look_accum / dt).limit_length(6.0)
	_look_accum = Vector2.ZERO
	return ActorIface.make_command(
			mv, rate,
			Input.is_action_just_pressed("jump"),
			Input.is_action_pressed("fire_primary"),
			Input.is_action_pressed("fire_secondary"),
			Input.is_action_just_pressed("interact"))

﻿class_name PilotController extends CharacterBody3D
## VS proxy for the TPS pilot. Fast, agile, wide awareness.
## Deliberately minimal: one rifle, no dodge/parkour (VS scope).

const SPEED_RUN := 8.5
const ACCEL := 40.0
const AIR_ACCEL := 14.0
const GRAVITY := 22.0
const JUMP_V := 7.5
const RIFLE_DMG := 22.0
const RIFLE_GAP := 0.16
const RIFLE_RANGE := 120.0

var yaw := 0.0
var pitch := 0.0
var control_enabled := true     # Director flips while piloting the mech

var _cam_yaw: Node3D
var _pitch_n: Node3D
var _spring: SpringArm3D
var _cam: Camera3D
var _muzzle: Marker3D
var health: Health
var _fire_cd := 0.0
var _anim: AnimationPlayer
var _anim_idle := ""
var _anim_run := ""
var _anim_gun_idle := ""
var _rifle_attached := false
var _skel: Skeleton3D
var _foot_bones: Array[int] = []
var _foot_air: Array[bool] = [false, false]


func _ready() -> void:
	collision_layer = 2
	collision_mask = 1 | 4
	var col := CollisionShape3D.new()
	col.name = "Col"
	var cap := CapsuleShape3D.new()
	cap.radius = 0.45
	cap.height = 1.8
	col.shape = cap
	col.position = Vector3(0, 0.9, 0)
	add_child(col)
	_muzzle = Marker3D.new()
	_muzzle.position = Vector3(0.35, 1.35, -0.7)
	add_child(_muzzle)
	_build_visual()
	_cam_yaw = Node3D.new()
	_cam_yaw.position = Vector3(0, 1.62, 0)
	add_child(_cam_yaw)
	_pitch_n = Node3D.new()
	_cam_yaw.add_child(_pitch_n)
	_spring = SpringArm3D.new()
	_spring.spring_length = 4.2
	_spring.margin = 0.25
	_spring.collision_mask = 1 | 2 | 4   # world + actors (mech hull) + enemies
	_pitch_n.add_child(_spring)
	_cam = Camera3D.new()
	_cam.fov = 78.0
	_cam.near = 0.1
	_spring.add_child(_cam)
	_spring.add_excluded_object(get_rid())
	# Flashlight: the pilot must see in the unlit lanes (night arena).
	var torch := SpotLight3D.new()
	torch.light_color = Color(1.0, 0.95, 0.85)
	torch.light_energy = 2.2
	torch.spot_range = 26.0
	torch.spot_angle = 32.0
	torch.position = Vector3(0.25, 1.5, -0.3)
	torch.rotation_degrees = Vector3(-8, 0, 0)
	_cam_yaw.add_child(torch)
	health = Health.new()
	health.name = "Health"
	health.max_hp = 100.0
	add_child(health)


func _mesh(pos: Vector3, color: Color) -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	var cap := CapsuleMesh.new()
	cap.radius = 0.42
	cap.height = 1.8
	mi.mesh = cap
	var mat := StandardMaterial3D.new()
	mat.albedo_color = color
	mi.material_override = mat
	mi.position = pos
	return mi


## Pilot visual: the vendored UAL glb ships its own skinned mannequin +
## all clips вЂ” plays natively with ZERO retargeting (per labs/pilot-loco).
## Fallback: static Synty pilot / greybox capsule.
func _build_visual() -> void:
	var ual: PackedScene = Synty.load_scene("ual_standard.glb")
	if ual != null:
		var inst := ual.instantiate() as Node3D
		var players := inst.find_children("*", "AnimationPlayer", true, false)
		_anim = players.front() if players.size() > 0 else null
		var has_mesh := inst.find_children("*", "MeshInstance3D", true, false).size() > 0
		if _anim != null and has_mesh:
			var wrap := Node3D.new()
			wrap.name = "PilotVisual"
			wrap.rotation.y = PI   # UAL mannequin faces +Z; face the travel dir
			wrap.add_child(inst)
			var aabb := Synty.fitted_aabb(wrap)
			if aabb.size.y > 0.01:
				var s := 1.8 / aabb.size.y
				wrap.scale = Vector3.ONE * s
				wrap.position = Vector3(0, -aabb.position.y * s + 0.02, 0)
			add_child(wrap)
			_resolve_anim_names()
			_attach_rifle(inst)
			_foot_bones.clear()
			var skel_list := inst.find_children("*", "Skeleton3D", true, false)
			if skel_list.size() > 0:
				_skel = skel_list.front() as Skeleton3D
				for bone_name in ["foot_l", "foot_r", "Ankle_L", "Ankle_R", "Foot_L", "Foot_R"]:
					var bi := _skel.find_bone(bone_name)
					if bi >= 0:
						_foot_bones.append(bi)
						if _foot_bones.size() == 2:
							break
			return
	# Fallback: static Synty pilot + rifle.
	var ps: PackedScene = Synty.load_scene("characters.fbx")
	if ps != null:
		var inst2 := ps.instantiate() as Node3D
		for mi in inst2.find_children("*", "MeshInstance3D", true, false):
			var m := mi as MeshInstance3D
			if m.name.findn("Female") >= 0:
				m.visible = false
			else:
				Synty._bind_palette(m)
		var wrap2 := Node3D.new()
		wrap2.name = "PilotVisual"
		wrap2.rotation.y = PI
		wrap2.add_child(inst2)
		var aabb2 := Synty.fitted_aabb(wrap2)
		if aabb2.size.y > 0.01:
			var s2 := 1.8 / aabb2.size.y
			wrap2.scale = Vector3.ONE * s2
			wrap2.position = Vector3(0, -aabb2.position.y * s2 + 0.02, 0)
		add_child(wrap2)
	else:
		add_child(_mesh(Vector3(0, 0.95, 0), Color(0.35, 0.55, 0.7)))
	var rifle := Synty.instance("rifle.fbx", 0.0)
	if rifle != null:
		var aabb := Synty.fitted_aabb(rifle)
		var longest := maxf(aabb.size.x, maxf(aabb.size.y, aabb.size.z))
		if longest > 0.01:
			rifle.scale = Vector3.ONE * (0.75 / longest)
		rifle.position = Vector3(0.55, 1.25, -0.1)
		rifle.rotation_degrees = Vector3(0, 90, 0)
		add_child(rifle)


func _resolve_anim_names() -> void:
	if _anim == null:
		return
	for anim_name in _anim.get_animation_list():
		var lower := String(anim_name).to_lower()
		if _anim_run == "" and (lower.contains("jog") or lower.contains("sprint")
				or lower.contains("run")):
			_anim_run = anim_name
		if _anim_idle == "" and lower.contains("idle") and not lower.contains("gun"):
			_anim_idle = anim_name
		if _anim_gun_idle == "" and lower.contains("pistol_idle"):
			_anim_gun_idle = anim_name
	if _anim_idle == "" and _anim.get_animation_list().size() > 0:
		_anim_idle = _anim.get_animation_list()[0]
	if _anim_idle != "":
		_anim.play(_anim_idle, 0.0)


func _update_anim() -> void:
	if _anim == null:
		return
	var hspeed := Vector2(velocity.x, velocity.z).length()
	var moving := hspeed > 1.5
	var want := _anim_run if (moving and _anim_run != "") else _anim_idle
	if not moving and _anim_gun_idle != "" and _rifle_attached:
		want = _anim_gun_idle   # weapon-ready idle when the rifle is out
	if want != "" and _anim.current_animation != want:
		_anim.play(want, 0.2)
	# Foot-slide calibration: clip authored at ~3.6 m/s jog.
	if _anim.current_animation == _anim_run:
		_anim.speed_scale = clampf(hspeed / 3.6, 0.8, 2.0)
	else:
		_anim.speed_scale = 1.0
	# Footstep thuds: a foot dropping below knee height while moving.
	if hspeed > 1.0 and _skel != null and _foot_bones.size() > 0:
		for i in range(_foot_bones.size()):
			var fy := _skel.get_bone_global_pose(_foot_bones[i]).origin.y
			var was_air := _foot_air[i]
			_foot_air[i] = fy > 0.22
			if was_air and not _foot_air[i]:
				Fx.play_sfx(self, Fx.thud_stream(), -16.0, randf_range(1.3, 1.6))


func _attach_rifle(inst: Node3D) -> void:
	var rifle := Synty.instance("rifle.fbx", 0.0)
	if rifle == null:
		return
	# Fit by longest axis: Synty weapons are oversized for a 1.8 m pilot.
	var aabb := Synty.fitted_aabb(rifle)
	var longest := maxf(aabb.size.x, maxf(aabb.size.y, aabb.size.z))
	if longest > 0.01:
		rifle.scale = Vector3.ONE * (0.75 / longest)
	var attached := false
	var skel_list := inst.find_children("*", "Skeleton3D", true, false)
	if skel_list.size() > 0:
		var skel := skel_list.front() as Skeleton3D
		var bone := -1
		for candidate in ["RightHand", "Hand_R", "hand_r", "R_Hand", "RightHandThumb1"]:
			bone = skel.find_bone(candidate)
			if bone >= 0:
				break
		if bone >= 0:
			var ba := BoneAttachment3D.new()
			ba.bone_idx = bone
			skel.add_child(ba)
			ba.add_child(rifle)
			rifle.position = Vector3(0.12, 0.18, 0.05)
			rifle.rotation_degrees = Vector3(0, 90, 0)
			attached = true
	if not attached:
		# Fallback: static side mount.
		rifle.position = Vector3(0.55, 1.25, -0.1)
		rifle.rotation_degrees = Vector3(0, 90, 0)
		add_child(rifle)
	# Bullets leave from the rifle itself, not from the body.
	if _muzzle.get_parent() != null:
		_muzzle.get_parent().remove_child(_muzzle)
	rifle.add_child(_muzzle)
	_muzzle.position = Vector3(0, 0.12, -0.55)   # barrel tip, rifle-local


func cam() -> Camera3D:
	return _cam


func apply_command(cmd: Dictionary, dt: float) -> void:
	if not control_enabled:
		cmd = ActorIface.empty_command()
	var look: Vector2 = cmd.look
	yaw = wrapf(yaw - look.x * dt, -PI, PI)
	pitch = clampf(pitch - look.y * dt, -1.25, 1.25)
	rotation.y = yaw
	_cam_yaw.rotation.y = 0.0            # body turns with yaw (TPS orbit is body-relative)
	_pitch_n.rotation.x = pitch

	var mv: Vector2 = cmd.mv
	var wish := (global_basis * Vector3(mv.x, 0.0, mv.y))
	wish.y = 0.0
	if wish.length_squared() > 1.0:
		wish = wish.normalized()
	var target := wish * SPEED_RUN
	var hvel := Vector3(velocity.x, 0, velocity.z)
	var acc := ACCEL if is_on_floor() else AIR_ACCEL
	hvel = hvel.move_toward(Vector3(target.x, 0, target.z), acc * dt)
	velocity.x = hvel.x
	velocity.z = hvel.z
	velocity.y -= GRAVITY * dt
	if cmd.jump and is_on_floor():
		velocity.y = JUMP_V
	move_and_slide()
	_update_anim()

	_fire_cd -= dt
	if control_enabled and cmd.fire_p and _fire_cd <= 0.0:
		_fire_cd = RIFLE_GAP
		_rifle_shot()


## Hitscan from the camera center, bullet converges from the muzzle onto the
## crosshair impact point (standard TPS convergence; keeps bot/human aim true).
func aim_eye() -> Vector3:
	return _cam.global_position


func _rifle_shot() -> void:
	var from := _cam.global_position
	var dir := -_cam.global_basis.z
	var to := from + dir * RIFLE_RANGE
	var probe := PhysicsRayQueryParameters3D.create(from, to, 1 | 4, [get_rid()])
	var aim_hit := get_world_3d().direct_space_state.intersect_ray(probe)
	var aim_point := to
	if aim_hit:
		aim_point = aim_hit.position as Vector3

	var origin := _muzzle.global_position
	var shot_dir := (aim_point - origin).normalized()
	var query := PhysicsRayQueryParameters3D.create(origin,
			origin + shot_dir * RIFLE_RANGE, 1 | 4, [get_rid()])
	var hit := get_world_3d().direct_space_state.intersect_ray(query)
	var end := origin + shot_dir * RIFLE_RANGE
	if hit:
		end = hit.position as Vector3
		ActorIface.apply_damage(hit.collider as Node,
				ActorIface.make_damage(RIFLE_DMG, ActorIface.Source.PILOT_GUN,
						0, end, shot_dir))
		Fx.burst(self, end, Color(1, 0.6, 0.3), 5, 4.0)
	Fx.tracer(self, origin, end)
	Fx.flash(self, origin, Color(1, 0.85, 0.5), 2.0, 0.04)
	Fx.play_sfx(self, Fx.shot_stream(), -4.0, randf_range(1.0, 1.2))


func take_damage(evt: Dictionary) -> void:
	health.take_damage(evt)
	Fx.burst(self, global_position + Vector3.UP, Color(0.8, 0.2, 0.2), 6, 3.0)
